def test_registered_schemas_are_current_and_include_metadata() -> None:
    """检查提交快照、严格构造枚举、开放线字符串和嵌套元数据。"""
    root = Path(__file__).resolve().parents[2]
    check_schemas(root / "contracts/schemas/probes")
    for model in PROBE_MODELS.values():
        assert checked_schema(model)["$schema"].endswith("2020-12/schema")
    wire = checked_schema(PageWireProbe)
    assert wire["properties"]["status"]["type"] == "string"
    assert "enum" not in wire["properties"]["status"]
    strict = checked_schema(StrictStatusProbe)
    assert strict["$defs"]["KnownStatus"]["enum"] == list(ENUM_DOMAINS["status"])
    envelope = checked_schema(WorkerEnvelopeProbe)
    assert envelope["properties"]["lease_token"]["digest"] == "exclude"
    assert envelope["properties"]["tenant_id"]["routable"] is True
    assert envelope["$defs"]["TombstoneProbe"]["properties"]["target"]["digest"] == "include"


@pytest.mark.parametrize("mutation", ["content", "missing", "extra"])
def test_schema_drift_is_rejected_without_rewriting(tmp_path: Path, mutation: str) -> None:
    """门禁必须发现改义、删文件和注册表漏项，普通检查不能自动修复。"""
