def test_default_expansion_and_exact_numeric_domains() -> None:
    """展开默认值是显式语义；JSON int64 保真不等于可以进入 JCS 安全整数域。"""
    request = envelope_payload()
    decoded = decode_wire(WorkerEnvelopeProbe, json.dumps(request).encode())
    dense = decoded.model_dump(mode="json")
    assert dense["page"]["status_reason"] is None
    assert dense["page"]["item_outcomes"] == []
    assert decoded.page.model_fields_set == {"status", "completeness", "tombstones"}
    assert canonical_sha256(dense) == canonical_sha256(decode_wire(WorkerEnvelopeProbe, decoded.model_dump_json().encode()).model_dump(mode="json"))
    assert dense["subjectseq"] == "18446744073709551615"
    request["lease_generation"] = 2**63-1
    exact = decode_wire(WorkerEnvelopeProbe, json.dumps(request).encode())
    assert exact.lease_generation == 2**63-1
    with pytest.raises(CanonicalizationError):
        canonical_sha256(exact.model_dump(mode="json"))


@pytest.mark.parametrize("status", (*ENUM_DOMAINS["status"], "future-status", "", "  future-status  "))
def test_wire_enums_remain_strings_until_semantic_classification(status: str) -> None:
    """所有已知值和未知原始值保持原样；构造侧对照仍拒绝未知值。"""
    request = envelope_payload()
    request["page"]["status"] = status
    page = decode_wire(WorkerEnvelopeProbe, json.dumps(request).encode()).page
    assert page.status == status
    if status not in ENUM_DOMAINS["status"]:
        assert unknown_enum_paths(page) == ["status"]
        with pytest.raises(ValidationError):
            StrictStatusProbe(status=status)
    else:
        assert unknown_enum_paths(page) == []
        assert StrictStatusProbe(status=status).status == status


