    """探针只在测试 app；检查内容类型、请求上限及自动 OpenAPI 模型。"""
    assert http_client.post("/_probe/worker", content=b"{}", headers={"content-type": "text/plain"}).status_code == 415
    assert http_client.post("/_probe/worker", content=b"x" * 65537, headers={"content-type": "application/json"}).status_code == 413
    assert "/_probe/worker" not in create_app().openapi()["paths"]
    spec = http_client.get("/openapi.json").json()
    assert spec["paths"]["/_probe/worker"]["post"]["requestBody"]["content"]["application/json"]["schema"]["$ref"].endswith("WorkerEnvelopeProbe")
    assert spec["components"]["schemas"]["PageWireProbe"]["properties"]["status"]["type"] == "string"
